// pyint.mjs
// Re-implementation of Python's built-in int(str) conversion semantics
// (base 10), used as the `type=int` callable for argument parsing.
//
// Accepted forms mirror CPython: optional surrounding whitespace, an
// optional '+'/'-' sign, decimal digits, and single underscores between
// digits (PEP 515). Anything else raises PyValueError, which the argument
// parser reports as "invalid int value".

export class PyValueError extends Error {
  constructor(message) {
    super(message);
    this.name = 'ValueError';
  }
}

// Python's str.strip() for int() removes whitespace such as
// space, \t, \n, \r, \f, \v. String#trim() covers all of these.
const INT_PATTERN = /^[+-]?\d(?:_?\d)*$/;

export function pyInt(text) {
  const stripped = String(text).trim();
  if (!INT_PATTERN.test(stripped)) {
    throw new PyValueError(
      `invalid literal for int() with base 10: ${pyRepr(stripped)}`
    );
  }
  return parseInt(stripped.replace(/_/g, ''), 10);
}

// Minimal Python repr() for strings: single-quoted, with backslash escapes.
export function pyRepr(value) {
  const s = String(value);
  let out = "'";
  for (const ch of s) {
    if (ch === '\\') out += '\\\\';
    else if (ch === "'") out += "\\'";
    else if (ch === '\n') out += '\\n';
    else if (ch === '\r') out += '\\r';
    else if (ch === '\t') out += '\\t';
    else out += ch;
  }
  return out + "'";
}

