// pybytes.mjs
// Re-implementation of Python's bytes(iterable_of_ints) constructor.
// Every element must be an integer in range(0, 256); otherwise a
// PyValueError is raised with CPython's exact message:
//   ValueError: bytes must be in range(0, 256)
//
// The result is a plain JavaScript array of byte values (0-255),
// keeping insertion order, used as the byte stream for struct parsing.

import { PyValueError } from './pyint.mjs';

export function pyBytes(values) {
  const bytes = [];
  for (const value of values) {
    if (!Number.isInteger(value) || value < 0 || value > 255) {
      throw new PyValueError('bytes must be in range(0, 256)');
    }
    bytes.push(value);
  }
  return bytes;
}

