// construct.mjs
// Minimal behavioral re-implementation of the `construct` library subset
// used by the source script: Struct, Int8ul and the Container result type.
//
// Byte streams are plain arrays of integers (0-255) produced by
// pyBytes(); parsing walks the array with a cursor.

// Raised when the byte stream ends before a field can be read,
// mirroring construct's StreamError.
export class StreamError extends Error {
  constructor(message) {
    super(message);
    this.name = 'StreamError';
  }
}

// Ordered key/value mapping printed exactly like construct's Container:
//   Container:
//       field1 = 91
//       field2 = 54
// (note the trailing space after "Container:").
export class Container {
  constructor() {
    this._keys = [];
    this._values = new Map();
  }

  set(key, value) {
    if (!this._values.has(key)) this._keys.push(key);
    this._values.set(key, value);
  }

  get(key) {
    return this._values.get(key);
  }

  toString() {
    const lines = this._keys.map(
      (key) => `    ${key} = ${String(this._values.get(key))}`
    );
    return 'Container: \n' + lines.join('\n');
  }
}

// Sequential cursor over a byte array, mirroring construct's stream reads.
export class ByteStream {
  constructor(bytes) {
    this.bytes = bytes;
    this.offset = 0;
  }

  read(count) {
    if (this.offset + count > this.bytes.length) {
      throw new StreamError(`could not read enough bytes, expected ${count}`);
    }
    const chunk = this.bytes.slice(this.offset, this.offset + count);
    this.offset += count;
    return chunk;
  }
}

// construct.Int8ul: unsigned 8-bit integer, little-endian (1 byte).
export const Int8ul = {
  size: 1,
  parse(stream) {
    return stream.read(1)[0];
  },
};

// construct.Struct: parses named fields in declaration order into a
// Container. Fields are supplied as [name, format] pairs, the JS
// equivalent of Python's `"name" / Format` syntax.
export class Struct {
  constructor(...fields) {
    this.fields = fields;
  }

  parse(data) {
    const stream = new ByteStream(data);
    const container = new Container();
    for (const [name, format] of this.fields) {
      container.set(name, format.parse(stream));
    }
    return container;
  }
}

