// argparse.mjs
// Minimal behavioral re-implementation of the Python argparse subset used
// by the source script: long options with `type` callables, `required`,
// `-h/--help`, `--opt value` and `--opt=value` forms, prefix abbreviation,
// and argparse's exact usage/error output with exit code 2.

import { pyRepr } from './pyint.mjs';

function basename(path) {
  const parts = String(path).split(/[\\/]/);
  return parts[parts.length - 1] || String(path);
}

// argparse treats a token starting with '-' as a value (not an option)
// when it looks like a negative number and no defined option does.
const NEGATIVE_NUMBER = /^-\d+$|^-\d*\.\d+$/;

function looksLikeOption(token) {
  if (token.length === 0 || token[0] !== '-') return false;
  if (token === '-') return false;
  if (NEGATIVE_NUMBER.test(token)) return false;
  return true;
}

export class ArgumentParser {
  constructor({ prog } = {}) {
    this.prog = prog || basename(process.argv[1] || 'prog');
    this.actions = [];
    this.addArgument(['-h', '--help'], {
      action: 'help',
      help: 'show this help message and exit',
    });
  }

  addArgument(flags, options = {}) {
    const flagList = Array.isArray(flags) ? flags : [flags];
    const longFlag = flagList.find((f) => f.startsWith('--')) || flagList[0];
    const dest = longFlag.replace(/^-+/, '').replace(/-/g, '_');
    this.actions.push({
      flags: flagList,
      dest,
      action: options.action || 'store',
      required: Boolean(options.required),
      type: options.type || null,
      help: options.help || null,
      metavar: options.metavar || dest.toUpperCase(),
    });
  }

  // ----- output formatting -------------------------------------------------

  formatUsage() {
    const parts = this.actions.map((a) => {
      const flag = a.flags[0];
      const body = a.action === 'help' ? flag : `${flag} ${a.metavar}`;
      return a.required ? body : `[${body}]`;
    });
    return `usage: ${this.prog} ${parts.join(' ')}\n`;
  }

  formatHelp() {
    const invocations = this.actions.map((a) => {
      if (a.action === 'help') return a.flags.join(', ');
      return a.flags.map((f) => `${f} ${a.metavar}`).join(', ');
    });
    // argparse: action_max_length includes the 2-space indent;
    // help_position = min(action_max_length + 2, max_help_position=24).
    const actionMaxLength = Math.max(...invocations.map((s) => s.length + 2));
    const helpPosition = Math.min(actionMaxLength + 2, 24);

    let out = this.formatUsage() + '\noptions:\n';
    this.actions.forEach((a, i) => {
      const header = '  ' + invocations[i];
      if (a.help) {
        out += header.padEnd(helpPosition) + a.help + '\n';
      } else {
        out += header + '\n';
      }
    });
    return out;
  }

  // ----- exits -------------------------------------------------------------

  printHelpAndExit() {
    process.stdout.write(this.formatHelp());
    process.exit(0);
  }

  error(message) {
    process.stderr.write(this.formatUsage());
    process.stderr.write(`${this.prog}: error: ${message}\n`);
    process.exit(2);
  }

  // ----- parsing -----------------------------------------------------------

  matchLongOption(name) {
    for (const action of this.actions) {
      if (action.flags.includes(name)) return action;
    }
    // allow_abbrev: unambiguous prefix of a long option also matches.
    const matches = [];
    for (const action of this.actions) {
      for (const flag of action.flags) {
        if (flag.startsWith('--') && flag.startsWith(name)) {
          if (!matches.includes(action)) matches.push(action);
        }
      }
    }
    if (matches.length === 1) return matches[0];
    if (matches.length > 1) {
      const options = matches
        .flatMap((a) => a.flags.filter((f) => f.startsWith(name)))
        .join(', ');
      this.error(`ambiguous option: ${name} could match ${options}`);
    }
    return null;
  }

  parseArgs(argv = process.argv.slice(2)) {
    const values = {};
    const extras = [];

    for (let i = 0; i < argv.length; i++) {
      const token = argv[i];

      if (!looksLikeOption(token)) {
        extras.push(token);
        continue;
      }

      let name = token;
      let inlineValue = null;
      const eq = token.indexOf('=');
      if (token.startsWith('--') && eq !== -1) {
        name = token.slice(0, eq);
        inlineValue = token.slice(eq + 1);
      }

      const action = token.startsWith('--')
        ? this.matchLongOption(name)
        : this.actions.find((a) => a.flags.includes(name)) || null;

      if (!action) {
        extras.push(token);
        continue;
      }

      if (action.action === 'help') {
        this.printHelpAndExit();
      }

      let raw;
      if (inlineValue !== null) {
        raw = inlineValue;
      } else if (i + 1 < argv.length && !looksLikeOption(argv[i + 1])) {
        raw = argv[++i];
      } else {
        this.error(`argument ${action.flags[0]}: expected one argument`);
      }

      if (action.type) {
        try {
          values[action.dest] = action.type(raw);
        } catch {
          this.error(
            `argument ${action.flags[0]}: invalid int value: ${pyRepr(raw)}`
          );
        }
      } else {
        values[action.dest] = raw;
      }
    }

    const missing = this.actions
      .filter((a) => a.required && !(a.dest in values))
      .map((a) => a.flags[0]);
    if (missing.length > 0) {
      this.error(`the following arguments are required: ${missing.join(', ')}`);
    }

    if (extras.length > 0) {
      this.error(`unrecognized arguments: ${extras.join(' ')}`);
    }

    return values;
  }
}

