// test4.mjs
// Node.js (ESM) port of /workspace/dataset/construct/test4.py.
// Parses --a and --b as ints, packs them into two bytes, parses them back
// through a two-field Int8ul struct, and prints the resulting Container.

import { ArgumentParser } from './lib/argparse.mjs';
import { pyInt, PyValueError } from './lib/pyint.mjs';
import { pyBytes } from './lib/pybytes.mjs';
import { Struct, Int8ul } from './lib/construct.mjs';

function main() {
  const parser = new ArgumentParser();
  parser.addArgument('--a', { type: pyInt, required: true });
  parser.addArgument('--b', { type: pyInt, required: true });
  const args = parser.parseArgs();

  const structFormat = new Struct(
    ['field1', Int8ul], // 定义第一个字段
    ['field2', Int8ul] // 定义第二个字段
  );
  const data = pyBytes([args.a, args.b]);
  const result = structFormat.parse(data); // 解析结构体
  console.log(String(result));
}

try {
  main();
} catch (err) {
  if (err instanceof PyValueError) {
    // Mirror the Python interpreter's unhandled-ValueError behavior:
    // traceback on stderr, exit code 1, nothing on stdout.
    process.stderr.write(
      'Traceback (most recent call last):\n' +
        '  File "test4.py", line 20, in <module>\n' +
        '  File "test4.py", line 15, in main\n' +
        `ValueError: ${err.message}\n`
    );
    process.exit(1);
  }
  throw err;
}

